import type { MetadataRoute } from "next";
import { loadV8DestinationCatalog } from "@/lib/data/destination-v8";
import { getSiteUrl } from "@/lib/site";

export default async function sitemap(): Promise<MetadataRoute.Sitemap> {
  const base = getSiteUrl();
  const catalog = await loadV8DestinationCatalog().catch(() => []);
  const greek = catalog.filter(item => item.countryCode === "GR");
  const languagePair = (el: string, en: string) => ({ languages: { "el-GR": el, "en-GB": en } });
  const pair=(elPath:string,enPath:string,frequency:"daily"|"weekly"|"monthly",priority:number)=>{
    const el=`${base}${elPath}`,en=`${base}${enPath}`,alternates=languagePair(el,en);
    return [{url:el,changeFrequency:frequency,priority,alternates},{url:en,changeFrequency:frequency,priority,alternates}];
  };
  return [
    { url: base, changeFrequency: "weekly", priority: 1, alternates: languagePair(base, `${base}/en`) },
    { url: `${base}/en`, changeFrequency: "weekly", priority: 1, alternates: languagePair(base, `${base}/en`) },
    ...pair("/ai-planner","/en/ai-planner","weekly",.98),
    ...pair("/stays-map","/en/stays-map","daily",.97),
    ...pair("/ai-map","/en/ai-map","daily",.96),
    ...pair("/proorismoi","/en/destinations","weekly",.95),
    ...pair("/seasonal","/en/seasonal","weekly",.88),
    ...pair("/guides","/en/guides","weekly",.86),
    ...pair("/how-ai-works","/en/how-ai-works","monthly",.8),
    ...greek.flatMap(item => {
      const el = `${base}/proorismoi/${item.slug}`;
      const en = `${base}/en/destinations/${item.slug}`;
      const alternates = languagePair(el, en);
      return [
        { url: el, changeFrequency: "monthly" as const, priority: .85, alternates },
        { url: en, changeFrequency: "monthly" as const, priority: .85, alternates },
      ];
    }),
  ];
}

import type { Metadata } from "next";
import { StayProductMapV32 } from "@/components/stay-product-map-v32";
import { V31PageFrame } from "@/components/v31-site-shell";

export const metadata:Metadata={title:"Χάρτης Διαμονών Ελλάδας | Live Offers | AI Greece Travel",description:"Διαδραστικός χάρτης πραγματικών καταλυμάτων και travel offers στην Ελλάδα, με markers τιμής, φίλτρα και ασφαλή μετάβαση στον συνεργάτη.",alternates:{canonical:"/stays-map",languages:{"el-GR":"/stays-map","en-GB":"/en/stays-map"}}};
export default function StaysMapPage(){return <V31PageFrame lang="el"><StayProductMapV32 lang="el"/></V31PageFrame>}

import { PrintTravelGuideV25 } from "@/components/print-travel-guide-v25";
import { TripadvisorProofV25 } from "@/components/tripadvisor-proof-v25";
import { buildTripBuilderV25 } from "@/lib/trip-builder/build-v25";
import type { TripadvisorPlaceV25 } from "@/lib/trip-builder/types-v25";
import { parseTripRequest } from "@/lib/validation/trip";
import styles from "./travel-guide-v25.module.css";

export const runtime="nodejs";export const dynamic="force-dynamic";
type Params={slug?:string;offer?:string;trip?:string};
const safeSlug=/^[a-z0-9-]{2,80}$/i,safeOffer=/^[a-zA-Z0-9:_-]{1,180}$/;
function decodeTrip(token:string){try{return JSON.parse(Buffer.from(token,"base64url").toString("utf8")) as unknown}catch{return null}}
function date(value:string,language:"el"|"en"){return new Intl.DateTimeFormat(language==="el"?"el-GR":"en-GB",{weekday:"long",day:"numeric",month:"long",year:"numeric"}).format(new Date(`${value}T12:00:00Z`))}
function Places({items}:{items:TripadvisorPlaceV25[]}){return <div className={styles.grid3}>{items.map(item=><article className={styles.card} key={`${item.kind}-${item.locationId}`}>{item.imageUrl?<img src={item.imageUrl} alt={item.name}/>:null}<small>{item.kind.toUpperCase()}</small><h3>{item.name}</h3><TripadvisorProofV25 item={item} compact/>{item.description?<p>{item.description.slice(0,300)}</p>:null}{item.address?<p><small>{item.address}</small></p>:null}{item.webUrl?<a href={item.webUrl} target="_blank" rel="noopener noreferrer">Tripadvisor ↗</a>:null}</article>)}</div>}

export default async function TravelGuidePage({searchParams}:{searchParams:Promise<Params>}){
 const q=await searchParams,slug=String(q.slug??"").toLowerCase(),offer=String(q.offer??""),raw=q.trip?decodeTrip(q.trip):null,parsed=parseTripRequest(raw);if(!safeSlug.test(slug)||!safeOffer.test(offer)||!parsed.success)return <main className={styles.page}><div className={styles.toolbar}>Invalid travel guide request.</div></main>;
 let plan;try{plan=await buildTripBuilderV25({trip:parsed.data,slug,offerId:offer})}catch{return <main className={styles.page}><div className={styles.toolbar}>This guide cannot be verified with the current stay/feed evidence. Return to the trip funnel and reselect the stay.</div></main>}
 const lang=plan.trip.language==="en"?"en":"el",name=lang==="el"?plan.destination.name:plan.destination.nameEn,ta=plan.tripadvisor,extra=plan.budgetBeyondHotel,truth=plan.availability.state.replaceAll("_"," "),web=plan.webResearch;
 return <main className={styles.page} data-canva-ready="true"><div className={styles.toolbar}><a href="/">← Travel Guru</a><PrintTravelGuideV25/></div><div className={styles.book}>
  <section className={`${styles.sheet} ${styles.cover}`}>{plan.stay?.imageUrl?<img className={styles.coverImage} src={plan.stay.imageUrl} alt={plan.stay.propertyName}/>:<div/>}<div><span className={styles.kicker}>PERSONAL TRAVEL GUIDE · V25 · CANVA-READY</span><h1>{name}</h1><h2>{date(plan.trip.startDate,lang)} → {date(plan.trip.endDate,lang)}</h2><p>{plan.trip.nights} night(s) · {plan.trip.groupSize} traveller(s) · {plan.stay?.propertyName}</p></div></section>
  <section className={styles.sheet}><div className={styles.heading}><div><span className={styles.kicker}>01 · STAY + AVAILABILITY TRUTH</span><h2>{plan.stay?.propertyName}</h2></div><span className={styles.badge}>{truth}</span></div><div className={styles.grid2}><div className={styles.card}>{plan.stay?.imageUrl?<img src={plan.stay.imageUrl} alt={plan.stay.propertyName}/>:null}<small>SELECTED STAY</small><h3>{plan.stay?.propertyName}</h3>{plan.stay?.price!=null?<p>Feed price signal: {plan.stay.currency??"EUR"} {plan.stay.price}</p>:null}<p>{plan.availability.reason}</p>{plan.stay?<a className={styles.cta} href={plan.stay.trackingUrl} target="_blank" rel="sponsored nofollow noopener">Final provider check ↗</a>:null}</div><div className={styles.card}><small>HOTEL SOCIAL PROOF</small>{ta.hotel?.imageUrl?<img src={ta.hotel.imageUrl} alt={ta.hotel.name}/>:null}<h3>{ta.hotel?.name??"No live Tripadvisor hotel match"}</h3>{ta.hotel?<><TripadvisorProofV25 item={ta.hotel}/>{ta.hotel.webUrl?<a href={ta.hotel.webUrl} target="_blank" rel="noopener noreferrer">View on Tripadvisor ↗</a>:null}</>:<p>{ta.note}</p>}</div></div><div className={styles.note}>Feed validity is not a booking. Only explicit stock/provider evidence is labelled confirmed; otherwise the final room and price must be checked on the provider page.</div><div className={styles.footer}>Tripadvisor content is rendered live and not stored. Popularity ranking, when shown, is cited with the source month/year.</div></section>
  <section className={styles.sheet}><div className={styles.heading}><div><span className={styles.kicker}>02 · WEATHER DAY BY DAY</span><h2>{plan.weather.label}</h2></div><span className={styles.badge}>{plan.weather.score??"—"}/100</span></div><div className={styles.weather}>{plan.weather.days.map(day=><article className={styles.card} key={day.date}><small>{date(day.date,lang)}</small><div className={styles.metric}>{day.temperatureMinC==null?"?":Math.round(day.temperatureMinC)}–{day.temperatureMaxC==null?"?":Math.round(day.temperatureMaxC)}°C</div><p>{day.summary}</p>{day.precipitationProbability!=null?<small>Rain {day.precipitationProbability}%</small>:null}</article>)}</div><div className={styles.note}>{plan.weather.days.some(day=>day.source==="typical")?"Dates outside the reliable short-range forecast horizon are shown as typical seasonal conditions, not as a false daily forecast.":"Daily short-range forecast for the selected dates."}</div></section>
  <section className={styles.sheet}><div className={styles.heading}><div><span className={styles.kicker}>03 · WEB RESEARCH + PLACES + MUSEUMS</span><h2>What to see around {name}</h2></div></div>{web.overview?<p>{web.overview}</p>:null}{web.bullets.length?<div className={styles.grid2}>{web.bullets.map(item=><article className={styles.card} key={item.name}><small>GROUNDED WEB RESEARCH · {item.strength}</small><h3>{item.name}</h3><p>{item.summary}</p>{item.why?<p><strong>Why it fits:</strong> {item.why}</p>:null}</article>)}</div>:null}{ta.status==="live"&&[...ta.places,...ta.museums].length?<><h3>Tripadvisor places / museums</h3><Places items={[...ta.places,...ta.museums]}/></>:null}{!web.bullets.length&&![...ta.places,...ta.museums].length?<div className={styles.note}>Not enough verified evidence was returned, so the guide does not invent POIs.</div>:null}{web.sources.length?<div className={styles.attribution}>Web sources: {web.sources.map(source=>source.domain).join(" · ")}</div>:null}</section>
  <section className={styles.sheet}><div className={styles.heading}><div><span className={styles.kicker}>04 · FOOD + DRINKS + NIGHTLIFE</span><h2>Top-ranked choices for your evenings</h2></div></div><h3>Restaurants</h3>{ta.restaurants.length?<Places items={ta.restaurants}/>:<div className={styles.note}>No live restaurant ranking returned.</div>}<h3>Bars / nightlife</h3>{ta.nightlife.length?<Places items={ta.nightlife}/>:<div className={styles.note}>No live nightlife result returned.</div>}<div className={styles.attribution}>Tripadvisor popularity ranking is displayed only when returned by the live Content API.</div></section>
  {plan.destination.isSummer?<section className={styles.sheet}><div className={styles.heading}><div><span className={styles.kicker}>05 · SUMMER BEACHES</span><h2>Beach options for these dates</h2></div></div>{ta.beaches.length?<Places items={ta.beaches}/>:<div className={styles.note}>No live Tripadvisor beach result was returned, so this guide does not invent a ranked beach list.</div>}</section>:null}
  <section className={styles.sheet}><div className={styles.heading}><div><span className={styles.kicker}>{plan.destination.isSummer?"06":"05"} · BUDGET BEYOND HOTEL</span><h2>Money to reserve for life outside the room</h2></div><span className={styles.badge}>EUR · GROUP TOTAL</span></div><div className={styles.grid2}><div className={styles.card}><small>FOOD</small><div className={styles.metric}>€{extra.foodLow}–€{extra.foodHigh}</div></div><div className={styles.card}><small>DRINKS / NIGHTLIFE</small><div className={styles.metric}>€{extra.drinksNightlifeLow}–€{extra.drinksNightlifeHigh}</div></div><div className={styles.card}><small>MUSEUMS / ACTIVITIES</small><div className={styles.metric}>€{extra.attractionsLow}–€{extra.attractionsHigh}</div></div><div className={styles.card}><small>LOCAL TRANSPORT</small><div className={styles.metric}>€{extra.localTransportLow}–€{extra.localTransportHigh}</div></div><div className={`${styles.card} ${styles.total}`}><small>TOTAL EXCLUDING HOTEL + INTERCITY TRANSPORT</small><div className={styles.metric}>€{extra.totalLow}–€{extra.totalHigh}</div></div></div><p className={styles.note}>{extra.note}</p></section>
  <section className={styles.sheet}><div className={styles.heading}><div><span className={styles.kicker}>{plan.destination.isSummer?"07":"06"} · FLEXIBLE DATE BACKUP</span><h2>Same weekday pattern only</h2></div></div><div className={styles.list}>{plan.flexibleWindows.map(window=><div className={styles.row} key={window.startDate}><strong>{date(window.startDate,lang)} → {date(window.endDate,lang)}</strong><span>{window.weatherLabel}</span><small>{window.availability.state.replaceAll("_"," ")}</small></div>)}</div><div className={styles.canva}><strong>Canva-ready content structure</strong><p>Reusable sections: cover, hotel, daily weather, grounded web POIs, Tripadvisor restaurants/nightlife, summer beaches, non-hotel budget and same-weekday alternatives. Live Tripadvisor fields remain no-store.</p><p>Template status: {plan.guide.canvaTemplateStatus}.</p></div><div className={styles.footer}>Generated {new Date(plan.generatedAt).toLocaleString("en-GB",{timeZone:"Europe/Athens"})} · Travel Guru V25</div></section>
 </div></main>
}

.v28-concierge-backdrop {
  position: fixed;
  inset: 0;
  z-index: 120;
  display: grid;
  place-items: center;
  padding: 22px;
  box-sizing: border-box;
  background: rgba(3, 20, 28, .72);
  backdrop-filter: blur(18px);
}

.v28-concierge-panel {
  width: min(1120px, 100%);
  max-height: min(860px, calc(100vh - 44px));
  overflow: auto;
  border: 1px solid rgba(255,255,255,.4);
  border-radius: 30px;
  background: #fffaf0;
  color: #0b2330;
  box-shadow: 0 40px 120px rgba(0,0,0,.34);
}

.v28-concierge-panel > header {
  position: sticky;
  z-index: 5;
  top: 0;
  min-height: 72px;
  padding: 14px 18px;
  box-sizing: border-box;
  display: flex;
  align-items: center;
  justify-content: space-between;
  border-bottom: 1px solid rgba(11,35,48,.1);
  background: rgba(255,250,240,.93);
  backdrop-filter: blur(16px);
}

.v28-concierge-title { display: flex; align-items: center; gap: 11px; }
.v28-concierge-title > span { width: 38px; height: 38px; display: grid; place-items: center; border-radius: 13px; color: white; background: linear-gradient(145deg,#ef6f5b,#d95241); }
.v28-concierge-title > div { display: grid; gap: 3px; }
.v28-concierge-title strong { font-size: 14px; }
.v28-concierge-title small { color: #75858b; font-size: 10px; }
.v28-concierge-close { width: 40px; height: 40px; display: grid; place-items: center; border: 1px solid rgba(11,35,48,.1); border-radius: 12px; background: white; color: #0b2330; }

.v28-concierge-loading {
  min-height: 620px;
  padding: 80px 32px;
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  background:
    radial-gradient(circle at 50% 35%, rgba(18,167,198,.12), transparent 24rem),
    #fffaf0;
}
.v28-orbit { position: relative; width: 108px; height: 108px; display: grid; place-items: center; margin-bottom: 22px; border-radius: 50%; color: #0d6f8c; background: white; box-shadow: 0 18px 50px rgba(11,35,48,.1); }
.v28-orbit::before,.v28-orbit::after { content:""; position:absolute; inset:-9px; border:1px solid rgba(13,111,140,.22); border-radius:50%; animation:v28Orbit 2.4s linear infinite; }
.v28-orbit::after { inset:-20px; animation-duration:3.8s; animation-direction:reverse; }
.v28-orbit span { position:absolute; width:8px; height:8px; border-radius:50%; background:#ef6f5b; top:1px; left:50%; transform:translateX(-50%); }
.v28-orbit span:last-child { top:auto; bottom:-8px; background:#12a7c6; }
.v28-concierge-loading h2 { max-width: 650px; margin: 0 0 26px; font-family: Georgia, serif; font-size: clamp(32px,4vw,52px); font-weight:500; line-height:1.03; letter-spacing:-.04em; }
.v28-agent-log { width:min(560px,100%); display:grid; gap:8px; text-align:left; }
.v28-agent-log p { margin:0; padding:11px 13px; display:flex; align-items:center; gap:8px; border:1px solid rgba(11,35,48,.08); border-radius:13px; background:rgba(255,255,255,.72); color:#52666e; font-size:11px; }
.v28-agent-log svg { color:#0d6f8c; flex:0 0 auto; }

.v28-concierge-results { padding: 38px; }
.v28-results-intro { max-width: 760px; margin-bottom: 28px; }
.v28-results-intro > span { color:#ef6f5b; font-size:10px; font-weight:900; letter-spacing:.17em; }
.v28-results-intro h2 { margin:10px 0 12px; font-family:Georgia,serif; font-size:clamp(34px,4vw,54px); font-weight:500; line-height:1.03; letter-spacing:-.04em; }
.v28-results-intro p { margin:0; color:#66787e; font-size:13px; line-height:1.65; }
.v28-quick-grid { display:grid; grid-template-columns:repeat(3,1fr); gap:14px; }
.v28-quick-grid article { overflow:hidden; border:1px solid rgba(11,35,48,.1); border-radius:22px; background:white; box-shadow:0 12px 35px rgba(11,35,48,.06); }
.v28-quick-photo { min-height:210px; padding:14px; box-sizing:border-box; display:flex; justify-content:space-between; align-items:flex-start; background-size:cover; background-position:center; }
.v28-quick-photo span,.v28-quick-photo strong { padding:7px 9px; border-radius:999px; background:rgba(4,29,39,.6); backdrop-filter:blur(10px); color:white; font-size:10px; }
.v28-quick-photo strong { color:#c4f3ec; }
.v28-quick-copy { padding:18px; }
.v28-quick-copy > small { color:#0d6f8c; font-size:9px; font-weight:900; letter-spacing:.08em; }
.v28-quick-copy h3 { margin:5px 0 8px; font-family:Georgia,serif; font-size:30px; font-weight:500; }
.v28-quick-copy p { min-height:76px; margin:0; color:#65777e; font-size:11px; line-height:1.55; }
.v28-quick-copy > div { margin:13px 0; display:flex; flex-wrap:wrap; gap:6px; }
.v28-quick-copy > div span { padding:6px 8px; border-radius:999px; background:#f4efe5; color:#586b72; font-size:9px; }
.v28-quick-copy button { width:100%; min-height:42px; display:flex; align-items:center; justify-content:space-between; padding:0 12px; border:0; border-radius:11px; background:#0b2330; color:white; font-size:10px; font-weight:850; }
.v28-results-actions { margin-top:22px; display:flex; justify-content:center; gap:9px; flex-wrap:wrap; }
.v28-results-actions button { min-height:42px; padding:0 14px; border:1px solid rgba(11,35,48,.12); border-radius:12px; background:white; color:#0b2330; font-size:10px; font-weight:800; }
.v28-results-actions button:first-child { border-color:#0b2330; background:#0b2330; color:white; }

.v28-concierge-error { min-height:520px; padding:70px 28px; box-sizing:border-box; display:flex; flex-direction:column; align-items:center; justify-content:center; text-align:center; }
.v28-concierge-error > svg { color:#ef6f5b; }
.v28-concierge-error h2 { margin:14px 0 8px; font-family:Georgia,serif; font-size:44px; font-weight:500; }
.v28-concierge-error p { max-width:580px; margin:0 0 22px; color:#66777d; font-size:13px; line-height:1.6; }
.v28-concierge-error button { min-height:46px; padding:0 16px; display:inline-flex; align-items:center; gap:8px; border:0; border-radius:12px; background:#0b2330; color:white; font-size:11px; font-weight:850; }

@keyframes v28Orbit { to { transform:rotate(360deg); } }

@media (max-width: 860px) {
  .v28-quick-grid { grid-template-columns:1fr; }
  .v28-quick-grid article { display:grid; grid-template-columns:.8fr 1.2fr; }
  .v28-quick-photo { min-height:230px; }
  .v28-quick-copy p { min-height:0; }
}

@media (max-width: 600px) {
  .v28-concierge-backdrop { padding:8px; align-items:end; }
  .v28-concierge-panel { max-height:94vh; border-radius:24px 24px 10px 10px; }
  .v28-concierge-title small { display:none; }
  .v28-concierge-results { padding:24px 14px 28px; }
  .v28-quick-grid article { display:block; }
  .v28-quick-photo { min-height:220px; }
  .v28-concierge-loading { min-height:540px; padding:60px 18px; }
}

@media (prefers-reduced-motion: reduce) {
  .v28-orbit::before,.v28-orbit::after { animation:none; }
}

/* Production bridge: V28 owns the visible chrome while V26 remains the decision engine.
   Use a general sibling because the concierge bridge sits between the V28 home and .guru-v9. */
.ai-greece-v28 ~ .guru-v9 .guru-nav,
.ai-greece-v28 ~ .guru-v9 .guru-hero,
.ai-greece-v28 ~ .guru-v9 .weekly-pick,
.ai-greece-v28 ~ .guru-v9 .guru-promise {
  display: none !important;
}

.ai-greece-v28 ~ .guru-v9 {
  padding-top: 0 !important;
  background: var(--v28-cream) !important;
  color: var(--v28-ink) !important;
}

.ai-greece-v28 ~ .guru-v9 .discovery {
  width: min(1180px, calc(100% - 40px));
  margin: 28px auto 100px;
  border: 1px solid var(--v28-line) !important;
  border-radius: 30px !important;
  background: rgba(255,255,255,.72) !important;
  box-shadow: 0 26px 70px rgba(11,35,48,.08) !important;
  overflow: hidden;
}

.ai-greece-v28 ~ .guru-v9 .discovery.open { animation: v28Reveal .45s ease both; }
.ai-greece-v28 ~ .guru-v9 .discovery-head {
  padding: 30px 32px 22px !important;
  border-bottom: 1px solid var(--v28-line);
  background: linear-gradient(135deg, rgba(223,246,246,.7), rgba(255,250,240,.9));
}
.ai-greece-v28 ~ .guru-v9 .discovery-head h2 { font-family: Georgia, serif !important; color: var(--v28-ink) !important; }
.ai-greece-v28 ~ .guru-v9 .discovery .eyebrow { color: var(--v28-coral) !important; }
.ai-greece-v28 ~ .guru-v9 .question-stage { padding: 28px 32px 34px !important; }
.ai-greece-v28 ~ .guru-v9 .question,
.ai-greece-v28 ~ .guru-v9 .question-card {
  border-color: var(--v28-line) !important;
  background: rgba(255,255,255,.88) !important;
}
.ai-greece-v28 ~ .guru-v9 button.primary,
.ai-greece-v28 ~ .guru-v9 .run-button,
.ai-greece-v28 ~ .guru-v9 .next-button {
  background: var(--v28-ink) !important;
  color: white !important;
  border-color: var(--v28-ink) !important;
}
.ai-greece-v28 ~ .guru-v9 .choice.active,
.ai-greece-v28 ~ .guru-v9 .mood-grid button.active {
  border-color: var(--v28-aegean) !important;
  background: #e4f4f5 !important;
  color: #075d76 !important;
}

.v28-intelligence {
  width: min(1180px, calc(100% - 40px));
  margin: 88px auto 96px;
  color: var(--v28-ink);
}
.v28-intelligence-head { max-width: 820px; margin-bottom: 34px; }
.v28-intelligence-head > span {
  display: inline-block;
  margin-bottom: 12px;
  color: var(--v28-coral);
  font: 800 12px/1.2 ui-sans-serif, system-ui, sans-serif;
  letter-spacing: .14em;
}
.v28-intelligence h2 {
  margin: 0;
  font-family: Georgia, "Times New Roman", serif;
  font-weight: 500;
  letter-spacing: -.035em;
}
.v28-intelligence-head h2 { font-size: clamp(2rem, 4vw, 3.6rem); line-height: 1.02; }
.v28-intelligence-head p {
  margin: 20px 0 0;
  color: rgba(11,35,48,.72);
  font-size: 1.06rem;
  line-height: 1.75;
}
.v28-intelligence-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 16px;
}
.v28-intelligence-grid article {
  padding: 28px;
  border: 1px solid var(--v28-line);
  border-radius: 24px;
  background: rgba(255,255,255,.72);
  box-shadow: 0 18px 50px rgba(11,35,48,.05);
}
.v28-intelligence-grid h3 {
  margin: 0 0 12px;
  font-family: Georgia, "Times New Roman", serif;
  font-size: 1.35rem;
  font-weight: 600;
}
.v28-intelligence-grid p,
.v28-faq p {
  margin: 0;
  color: rgba(11,35,48,.72);
  line-height: 1.68;
}
.v28-faq {
  display: grid;
  grid-template-columns: .8fr 1.2fr;
  gap: 46px;
  margin-top: 54px;
  padding-top: 38px;
  border-top: 1px solid var(--v28-line);
}
.v28-faq > h2 { font-size: clamp(1.7rem, 3vw, 2.5rem); line-height: 1.08; }
.v28-faq details { border-bottom: 1px solid var(--v28-line); }
.v28-faq summary {
  cursor: pointer;
  padding: 17px 28px 17px 0;
  font-weight: 750;
  line-height: 1.4;
}
.v28-faq details p { padding: 0 28px 18px 0; }

@media (max-width: 900px) {
  .v28-intelligence-grid { grid-template-columns: 1fr; }
  .v28-faq { grid-template-columns: 1fr; gap: 20px; }
}

@media (max-width: 680px) {
  .ai-greece-v28 ~ .guru-v9 .discovery {
    width: calc(100% - 28px);
    border-radius: 22px !important;
  }
  .ai-greece-v28 ~ .guru-v9 .discovery-head,
  .ai-greece-v28 ~ .guru-v9 .question-stage {
    padding-left: 18px !important;
    padding-right: 18px !important;
  }
  .v28-intelligence { width: calc(100% - 28px); margin: 62px auto 72px; }
  .v28-intelligence-grid article { padding: 22px; border-radius: 20px; }
}

:root {
  --v28-ink: #0b2330;
  --v28-ink-soft: #24404b;
  --v28-aegean: #0d6f8c;
  --v28-aegean-bright: #12a7c6;
  --v28-sea: #dff6f6;
  --v28-sand: #f3ead9;
  --v28-cream: #fffaf0;
  --v28-white: #ffffff;
  --v28-coral: #ef6f5b;
  --v28-olive: #7d8f63;
  --v28-line: rgba(11, 35, 48, 0.12);
  --v28-shadow: 0 28px 70px rgba(11, 35, 48, 0.13);
}

html { scroll-behavior: smooth; }
body { margin: 0; background: var(--v28-cream); color: var(--v28-ink); }
button, textarea, input, select { font: inherit; }

.ai-greece-v28 {
  min-height: 100vh;
  overflow: hidden;
  background:
    radial-gradient(circle at 8% 18%, rgba(18, 167, 198, .09), transparent 28rem),
    radial-gradient(circle at 92% 48%, rgba(239, 111, 91, .08), transparent 26rem),
    var(--v28-cream);
  color: var(--v28-ink);
  font-family: "Avenir Next", "Segoe UI", sans-serif;
}

.ai-greece-v28 a { color: inherit; text-decoration: none; }
.ai-greece-v28 button { cursor: pointer; }

.v28-nav {
  position: fixed;
  z-index: 70;
  top: 16px;
  left: 50%;
  transform: translateX(-50%);
  width: min(1180px, calc(100% - 32px));
  min-height: 66px;
  box-sizing: border-box;
  padding: 10px 12px 10px 14px;
  border: 1px solid rgba(255, 255, 255, .6);
  border-radius: 22px;
  background: rgba(255, 250, 240, .88);
  box-shadow: 0 15px 50px rgba(10, 35, 48, .14);
  backdrop-filter: blur(20px) saturate(140%);
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  gap: 22px;
}

.v28-brand { display: inline-flex; align-items: center; gap: 10px; width: fit-content; }
.v28-brand-mark {
  width: 42px;
  height: 42px;
  display: grid;
  place-items: center;
  border-radius: 14px;
  color: white;
  background: linear-gradient(145deg, var(--v28-aegean), #06495f);
  box-shadow: inset 0 1px 0 rgba(255,255,255,.24), 0 8px 18px rgba(13,111,140,.22);
}
.v28-brand > span:last-child { display: grid; line-height: 1.03; }
.v28-brand strong { font-size: 14px; letter-spacing: .12em; }
.v28-brand small { margin-top: 5px; color: #6c7c83; font-size: 10px; letter-spacing: .04em; }
.v28-nav nav { display: flex; align-items: center; gap: 28px; font-size: 13px; font-weight: 700; color: #405761; }
.v28-nav nav a { transition: color .2s ease, transform .2s ease; }
.v28-nav nav a:hover { color: var(--v28-aegean); transform: translateY(-1px); }
.v28-nav-actions { display: flex; align-items: center; justify-content: flex-end; gap: 12px; }
.v28-language { display: flex; padding: 3px; border: 1px solid var(--v28-line); border-radius: 999px; background: rgba(255,255,255,.64); }
.v28-language a { min-width: 31px; padding: 6px 8px; border-radius: 999px; text-align: center; font-size: 11px; font-weight: 800; color: #75848a; }
.v28-language a.active { background: var(--v28-ink); color: white; }
.v28-nav-actions > button {
  min-height: 42px;
  padding: 0 17px;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  border: 0;
  border-radius: 13px;
  color: white;
  background: var(--v28-ink);
  font-size: 12px;
  font-weight: 800;
}

.v28-hero {
  position: relative;
  min-height: 850px;
  margin: 0 auto;
  background: #063a4e;
  isolation: isolate;
}
.v28-hero-photo {
  position: absolute;
  inset: 0;
  z-index: -3;
  background-image: url('/api/destination-photo?slug=milos');
  background-size: cover;
  background-position: center 46%;
  transform: scale(1.01);
}
.v28-hero-scrim {
  position: absolute;
  inset: 0;
  z-index: -2;
  background:
    linear-gradient(90deg, rgba(4, 28, 38, .87) 0%, rgba(5, 37, 50, .69) 43%, rgba(5, 37, 50, .15) 74%, rgba(5, 37, 50, .26) 100%),
    linear-gradient(0deg, rgba(5, 36, 48, .68) 0%, transparent 34%, rgba(5, 36, 48, .14) 100%);
}
.v28-hero::after {
  content: "";
  position: absolute;
  inset: auto 0 0;
  z-index: -1;
  height: 200px;
  background: linear-gradient(0deg, rgba(5,31,42,.9), transparent);
}
.v28-hero-content {
  width: min(1180px, calc(100% - 40px));
  min-height: 750px;
  margin: 0 auto;
  padding: 150px 0 120px;
  box-sizing: border-box;
  display: grid;
  grid-template-columns: minmax(0, 1.08fr) minmax(390px, .72fr);
  gap: 70px;
  align-items: center;
}
.v28-hero-copy { color: white; max-width: 700px; }
.v28-kicker, .v28-overline {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 11px;
  font-weight: 900;
  letter-spacing: .18em;
  text-transform: uppercase;
}
.v28-kicker { color: #b5f6f4; }
.v28-hero-copy h1 {
  margin: 20px 0 22px;
  max-width: 760px;
  font-family: Georgia, "Times New Roman", serif;
  font-size: clamp(50px, 6.5vw, 94px);
  line-height: .91;
  letter-spacing: -.055em;
  font-weight: 500;
}
.v28-hero-copy h1 span, .v28-hero-copy h1 em { display: block; }
.v28-hero-copy h1 em { color: #c5f2ed; font-weight: 400; }
.v28-hero-copy p { max-width: 650px; margin: 0; font-size: 18px; line-height: 1.62; color: rgba(255,255,255,.82); }
.v28-proof-row { margin-top: 30px; display: flex; gap: 12px; flex-wrap: wrap; }
.v28-proof-row span { padding: 9px 12px; display: inline-flex; align-items: center; gap: 7px; border: 1px solid rgba(255,255,255,.16); border-radius: 999px; background: rgba(255,255,255,.08); backdrop-filter: blur(10px); font-size: 12px; color: rgba(255,255,255,.84); }

.v28-composer {
  padding: 24px;
  border: 1px solid rgba(255,255,255,.5);
  border-radius: 28px;
  background: rgba(255,250,240,.94);
  color: var(--v28-ink);
  box-shadow: 0 32px 85px rgba(0,0,0,.25);
  backdrop-filter: blur(22px);
}
.v28-composer-head { display: flex; align-items: center; gap: 12px; }
.v28-ai-dot { width: 39px; height: 39px; display: grid; place-items: center; flex: 0 0 auto; color: white; border-radius: 13px; background: linear-gradient(145deg, var(--v28-coral), #dd5543); box-shadow: 0 9px 20px rgba(239,111,91,.25); }
.v28-composer-head > div { display: grid; gap: 3px; }
.v28-composer-head strong { font-size: 15px; }
.v28-composer-head small { color: #738087; font-size: 11px; line-height: 1.4; }
.v28-composer textarea {
  width: 100%;
  min-height: 126px;
  margin: 18px 0 14px;
  box-sizing: border-box;
  resize: vertical;
  padding: 16px 17px;
  border: 1px solid rgba(11,35,48,.14);
  outline: none;
  border-radius: 17px;
  background: white;
  color: var(--v28-ink);
  font-size: 14px;
  line-height: 1.55;
  transition: border-color .2s ease, box-shadow .2s ease;
}
.v28-composer textarea:focus { border-color: rgba(13,111,140,.55); box-shadow: 0 0 0 4px rgba(18,167,198,.09); }
.v28-composer textarea::placeholder { color: #98a3a7; }
.v28-mood-list { display: flex; flex-wrap: wrap; gap: 7px; }
.v28-mood-list button { padding: 8px 10px; display: inline-flex; align-items: center; gap: 6px; border: 1px solid rgba(11,35,48,.1); border-radius: 999px; background: #f7f2e8; color: #51646c; font-size: 11px; font-weight: 700; transition: .2s ease; }
.v28-mood-list button:hover { transform: translateY(-1px); }
.v28-mood-list button.active { border-color: var(--v28-aegean); background: #e4f4f5; color: #075d76; }
.v28-submit { width: 100%; min-height: 54px; margin-top: 17px; padding: 0 17px; display: flex; align-items: center; justify-content: space-between; border: 0; border-radius: 16px; background: var(--v28-ink); color: white; font-size: 14px; font-weight: 850; transition: transform .2s ease, box-shadow .2s ease; }
.v28-submit:hover { transform: translateY(-2px); box-shadow: 0 13px 24px rgba(11,35,48,.18); }
.v28-composer-foot { margin-top: 11px; display: flex; align-items: center; justify-content: space-between; gap: 10px; color: #829096; font-size: 10px; }
.v28-composer-foot span { display: inline-flex; align-items: center; gap: 5px; }

.v28-hero-rail {
  position: absolute;
  left: 50%;
  bottom: 28px;
  transform: translateX(-50%);
  width: min(1180px, calc(100% - 40px));
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  border: 1px solid rgba(255,255,255,.15);
  border-radius: 20px;
  overflow: hidden;
  background: rgba(3,28,39,.56);
  backdrop-filter: blur(18px);
}
.v28-hero-rail button { min-height: 82px; padding: 16px 20px; display: grid; grid-template-columns: 24px 1fr; grid-template-rows: auto auto; column-gap: 10px; text-align: left; border: 0; border-right: 1px solid rgba(255,255,255,.13); color: white; background: transparent; transition: background .2s ease; }
.v28-hero-rail button:last-child { border-right: 0; }
.v28-hero-rail button:hover { background: rgba(255,255,255,.08); }
.v28-hero-rail svg { grid-row: 1 / 3; align-self: center; color: #b9f4ee; }
.v28-hero-rail span { font-size: 13px; font-weight: 800; }
.v28-hero-rail small { margin-top: 4px; font-size: 10px; color: rgba(255,255,255,.6); }

.v28-section { width: min(1180px, calc(100% - 40px)); margin: 0 auto; padding: 120px 0; }
.v28-section-head { display: grid; grid-template-columns: 1.35fr .65fr; gap: 70px; align-items: end; margin-bottom: 45px; }
.v28-section-head.compact { grid-template-columns: 1fr; }
.v28-overline { color: var(--v28-coral); }
.v28-section-head h2, .v28-region-copy h2, .v28-final-cta h2 {
  margin: 14px 0 0;
  font-family: Georgia, "Times New Roman", serif;
  font-size: clamp(38px, 4.4vw, 67px);
  font-weight: 500;
  line-height: 1.02;
  letter-spacing: -.045em;
}
.v28-section-head > p { margin: 0 0 6px; color: #61747b; line-height: 1.65; font-size: 14px; }

.v28-destination-grid {
  display: grid;
  grid-template-columns: 1.3fr .7fr 1fr;
  grid-template-rows: 260px 260px;
  gap: 16px;
}
.v28-destination-card { position: relative; min-height: 260px; overflow: hidden; padding: 0; border: 0; border-radius: 24px; color: white; text-align: left; background: #0c455b; box-shadow: 0 10px 35px rgba(11,35,48,.08); isolation: isolate; }
.v28-destination-card.card-1 { grid-row: 1 / 3; }
.v28-destination-card.card-4 { grid-column: 2 / 4; }
.v28-card-photo, .v28-card-shade { position: absolute; inset: 0; }
.v28-card-photo { z-index: -2; background-size: cover; background-position: center; transition: transform .65s cubic-bezier(.2,.8,.2,1); }
.v28-card-shade { z-index: -1; background: linear-gradient(0deg, rgba(4,29,39,.76), rgba(4,29,39,.05) 70%); }
.v28-destination-card:hover .v28-card-photo { transform: scale(1.045); }
.v28-match { position: absolute; top: 16px; right: 16px; padding: 8px 10px; display: inline-flex; align-items: baseline; gap: 5px; border: 1px solid rgba(255,255,255,.2); border-radius: 999px; background: rgba(4,29,39,.48); backdrop-filter: blur(12px); font-size: 9px; letter-spacing: .05em; text-transform: uppercase; }
.v28-match strong { font-size: 13px; color: #c9f5ef; }
.v28-card-copy { position: absolute; left: 22px; right: 22px; bottom: 20px; display: grid; }
.v28-card-copy small { color: rgba(255,255,255,.68); font-size: 10px; letter-spacing: .04em; }
.v28-card-copy strong { margin: 5px 0 10px; font-family: Georgia, serif; font-size: 32px; font-weight: 500; }
.v28-card-copy > span { display: inline-flex; align-items: center; gap: 6px; font-size: 11px; font-weight: 800; }

.v28-regions { display: grid; grid-template-columns: .75fr 1.25fr; gap: 85px; align-items: center; border-top: 1px solid var(--v28-line); }
.v28-region-copy h2 em { color: var(--v28-aegean); font-weight: 400; }
.v28-region-copy p { max-width: 520px; margin: 25px 0; color: #61747b; font-size: 14px; line-height: 1.7; }
.v28-region-copy > button { min-height: 46px; padding: 0 16px; display: inline-flex; align-items: center; gap: 8px; border: 1px solid var(--v28-line); border-radius: 13px; background: white; color: var(--v28-ink); font-size: 12px; font-weight: 800; box-shadow: 0 8px 24px rgba(11,35,48,.06); }
.v28-region-board { position: relative; min-height: 460px; padding: 54px 40px; box-sizing: border-box; display: grid; gap: 10px; align-content: center; border-radius: 34px; overflow: hidden; background:
  linear-gradient(135deg, rgba(9,94,119,.96), rgba(7,50,67,.96)),
  url('/api/destination-photo?slug=chania') center/cover;
  box-shadow: var(--v28-shadow);
}
.v28-region-board::before { content: "GREECE"; position: absolute; top: -18px; right: -8px; color: rgba(255,255,255,.035); font-size: 132px; font-weight: 900; letter-spacing: -.07em; }
.v28-region-board button { position: relative; min-height: 76px; padding: 12px 14px; display: grid; grid-template-columns: 42px 1fr 22px; align-items: center; gap: 10px; border: 1px solid rgba(255,255,255,.12); border-radius: 17px; text-align: left; color: white; background: rgba(255,255,255,.07); transition: transform .2s ease, background .2s ease; }
.v28-region-board button:hover { transform: translateX(6px); background: rgba(255,255,255,.12); }
.v28-region-board button > svg:first-child { color: #bbf1e9; }
.v28-region-board button span { display: grid; gap: 4px; }
.v28-region-board button strong { font-size: 14px; }
.v28-region-board button small { color: rgba(255,255,255,.58); font-size: 10px; }

.v28-how { border-top: 1px solid var(--v28-line); }
.v28-how-grid { display: grid; grid-template-columns: repeat(4, 1fr); border-top: 1px solid var(--v28-line); border-bottom: 1px solid var(--v28-line); }
.v28-how-grid article { min-height: 260px; padding: 28px 24px; box-sizing: border-box; border-right: 1px solid var(--v28-line); }
.v28-how-grid article:last-child { border-right: 0; }
.v28-how-grid article > span { display: block; margin-bottom: 38px; color: #9caaa9; font-size: 10px; letter-spacing: .1em; }
.v28-how-grid article > svg { color: var(--v28-aegean); }
.v28-how-grid h3 { margin: 14px 0 9px; font-size: 16px; }
.v28-how-grid p { margin: 0; color: #697a80; font-size: 12px; line-height: 1.62; }

.v28-weekly {
  width: min(1180px, calc(100% - 40px));
  min-height: 520px;
  margin: 20px auto 120px;
  display: grid;
  grid-template-columns: 1.15fr .85fr;
  overflow: hidden;
  border-radius: 34px;
  background: var(--v28-ink);
  color: white;
  box-shadow: var(--v28-shadow);
}
.v28-weekly-photo { min-height: 520px; background-size: cover; background-position: center; }
.v28-weekly-copy { padding: 68px 58px; display: flex; flex-direction: column; justify-content: center; align-items: flex-start; }
.v28-weekly-copy .v28-overline { color: #bbf1e9; }
.v28-weekly-copy h2 { margin: 12px 0 14px; font-family: Georgia, serif; font-size: 56px; font-weight: 500; }
.v28-weekly-copy p { margin: 0 0 25px; color: rgba(255,255,255,.68); font-size: 14px; line-height: 1.7; }
.v28-weekly-copy button { min-height: 47px; padding: 0 16px; display: inline-flex; align-items: center; gap: 8px; border: 0; border-radius: 13px; background: #c6f0e9; color: #0b3240; font-size: 12px; font-weight: 850; }

.v28-final-cta {
  width: min(1180px, calc(100% - 40px));
  margin: 0 auto 60px;
  padding: 95px 38px;
  box-sizing: border-box;
  text-align: center;
  border-radius: 34px;
  color: white;
  background:
    radial-gradient(circle at 18% 10%, rgba(18,167,198,.34), transparent 24rem),
    radial-gradient(circle at 85% 85%, rgba(239,111,91,.24), transparent 28rem),
    var(--v28-ink);
}
.v28-final-cta > div { display: inline-flex; align-items: center; gap: 8px; color: #bdf0ea; font-size: 10px; font-weight: 900; letter-spacing: .18em; }
.v28-final-cta h2 { max-width: 900px; margin: 18px auto 28px; }
.v28-final-cta h2 em { color: #beece7; font-weight: 400; }
.v28-final-cta > button { min-height: 52px; padding: 0 20px; display: inline-flex; align-items: center; gap: 9px; border: 0; border-radius: 14px; background: white; color: var(--v28-ink); font-size: 12px; font-weight: 850; }

/* Bridge into the validated V26 decision funnel: V28 owns the chrome, V26 owns the engine. */
.ai-greece-v28 + .guru-v9 .guru-nav,
.ai-greece-v28 + .guru-v9 .guru-hero,
.ai-greece-v28 + .guru-v9 .weekly-pick,
.ai-greece-v28 + .guru-v9 .guru-promise { display: none !important; }

.ai-greece-v28 + .guru-v9 {
  padding-top: 0 !important;
  background: var(--v28-cream) !important;
  color: var(--v28-ink) !important;
}
.ai-greece-v28 + .guru-v9 .discovery {
  width: min(1180px, calc(100% - 40px));
  margin: 28px auto 100px;
  border: 1px solid var(--v28-line) !important;
  border-radius: 30px !important;
  background: rgba(255,255,255,.72) !important;
  box-shadow: 0 26px 70px rgba(11,35,48,.08) !important;
  overflow: hidden;
}
.ai-greece-v28 + .guru-v9 .discovery.open { animation: v28Reveal .45s ease both; }
.ai-greece-v28 + .guru-v9 .discovery-head { padding: 30px 32px 22px !important; border-bottom: 1px solid var(--v28-line); background: linear-gradient(135deg, rgba(223,246,246,.7), rgba(255,250,240,.9)); }
.ai-greece-v28 + .guru-v9 .discovery-head h2 { font-family: Georgia, serif !important; color: var(--v28-ink) !important; }
.ai-greece-v28 + .guru-v9 .discovery .eyebrow { color: var(--v28-coral) !important; }
.ai-greece-v28 + .guru-v9 .question-stage { padding: 28px 32px 34px !important; }
.ai-greece-v28 + .guru-v9 .question,
.ai-greece-v28 + .guru-v9 .question-card { border-color: var(--v28-line) !important; background: rgba(255,255,255,.88) !important; }
.ai-greece-v28 + .guru-v9 button.primary,
.ai-greece-v28 + .guru-v9 .run-button,
.ai-greece-v28 + .guru-v9 .next-button { background: var(--v28-ink) !important; color: white !important; border-color: var(--v28-ink) !important; }
.ai-greece-v28 + .guru-v9 .choice.active,
.ai-greece-v28 + .guru-v9 .mood-grid button.active { border-color: var(--v28-aegean) !important; background: #e4f4f5 !important; color: #075d76 !important; }

@keyframes v28Reveal { from { opacity: 0; transform: translateY(18px); } to { opacity: 1; transform: translateY(0); } }

@media (max-width: 980px) {
  .v28-nav { grid-template-columns: 1fr auto; }
  .v28-nav nav { display: none; }
  .v28-hero { min-height: 980px; }
  .v28-hero-content { min-height: 860px; grid-template-columns: 1fr; gap: 35px; padding-top: 125px; align-content: center; }
  .v28-hero-copy { max-width: 760px; }
  .v28-hero-copy h1 { max-width: 720px; font-size: clamp(52px, 9vw, 80px); }
  .v28-composer { max-width: 620px; }
  .v28-section-head { grid-template-columns: 1fr; gap: 20px; }
  .v28-destination-grid { grid-template-columns: 1fr 1fr; grid-template-rows: 320px 260px 260px; }
  .v28-destination-card.card-1 { grid-row: auto; }
  .v28-destination-card.card-4 { grid-column: 1 / 3; }
  .v28-regions { grid-template-columns: 1fr; gap: 38px; }
  .v28-how-grid { grid-template-columns: 1fr 1fr; }
  .v28-how-grid article:nth-child(2) { border-right: 0; }
  .v28-how-grid article:nth-child(-n+2) { border-bottom: 1px solid var(--v28-line); }
  .v28-weekly { grid-template-columns: 1fr; }
  .v28-weekly-photo { min-height: 400px; }
}

