import { FormEvent,useMemo,useState } from "react";
import type { V8StayOffer } from "@/lib/decision/v8-types";
import type { TripRequest } from "@/lib/validation/trip";
import type { TripBuilderPlanV25 } from "@/lib/trip-builder/types-v25";

type Props={slug:string;name:string;nameEn:string;trip:TripRequest;offers:V8StayOffer[];lang?:"el"|"en";missionId?:string|null};
const say=(lang:"el"|"en",el:string,en:string)=>lang==="el"?el:en;

export function V33EscapeBuilderClient({slug,name,nameEn,trip,offers,lang="el",missionId=null}:Props){
 const[selected,setSelected]=useState<V8StayOffer|null>(offers[0]??null),[plan,setPlan]=useState<TripBuilderPlanV25|null>(null),[busy,setBusy]=useState(false),[error,setError]=useState<string|null>(null),[email,setEmail]=useState(""),[mailState,setMailState]=useState<"idle"|"sending"|"sent"|"error">("idle");
 const destination=lang==="en"?nameEn:name,photo=selected?.imageUrl||selected?.thumbUrl||null,total=plan?.budgetBeyondHotel,guideUrl=plan?.guide.path||"",currentOffer=plan?.stay?.trackingUrl||selected?.trackingUrl||"",weatherSummary=useMemo(()=>plan?.weather.days.slice(0,5)??[],[plan]);

 async function persistCompleted(built:TripBuilderPlanV25){
  if(!missionId)return;
  const media=[built.stay?.imageUrl?{kind:"stay",url:built.stay.imageUrl}:null,...built.tripadvisor.places.map(x=>x.imageUrl?{kind:x.kind,url:x.imageUrl,name:x.name}:null),...built.tripadvisor.restaurants.map(x=>x.imageUrl?{kind:"restaurant",url:x.imageUrl,name:x.name}:null)].filter(Boolean).slice(0,20);
  await fetch("/api/escape/research/complete",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({missionId,destinationId:slug,weather:built.weather,places:built.webResearch.bullets,restaurants:built.tripadvisor.restaurants,practicalNotes:built.webResearch.practicalNotes,logistics:{availability:built.availability,flexibleWindows:built.flexibleWindows,budgetBeyondHotel:built.budgetBeyondHotel},sources:built.webResearch.sources,media,guidePath:built.guide.path,trackingUrl:built.stay?.trackingUrl??selected?.trackingUrl??null})}).catch(()=>null);
 }
 async function build(){
  if(!selected)return;setBusy(true);setError(null);setPlan(null);
  try{
   if(missionId)await fetch("/api/escape/select",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({missionId,destinationId:slug})}).catch(()=>null);
   const response=await fetch("/api/trip-builder",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({trip,slug,offerId:selected.sourceProductId})});if(!response.ok)throw new Error(`HTTP ${response.status}`);
   const built=await response.json() as TripBuilderPlanV25;setPlan(built);void persistCompleted(built);
