import styles from "./v38-escape-builder.module.css";

type Lang="el"|"en";
type Stage="cinema"|"research"|"explore"|"stay"|"verify"|"email"|"unlocked";
type Media={imageUrl:string;originalUrl?:string;sourceUrl:string;title:string;description?:string;license:string;attribution:string};
type ResearchPlace={id?:string;name:string;summary?:string|null;whyItFits?:string|null};
type Dossier={
 release?:string;
 destination:{slug:string;name:string;nameEn:string;latitude:number;longitude:number;isSummer:boolean};
 weather:{label:string;score:number|null;days:Array<{date:string;temperatureMinC:number|null;temperatureMaxC:number|null;precipitationProbability?:number|null;summary:string}>};
 localIntelligence:LocalIntelligenceV38;
 research:{source:string;overview:string|null;attractions:ResearchPlace[];practicalNotes:string[];sources:Array<{title:string;url:string;domain:string}>};
 budgetBeyondHotel:{totalLow:number;totalHigh:number;note:string};
};
type Tab="highlights"|"eat"|"drinks"|"culture"|"sea"|"practical";

type Props={slug:string;name:string;nameEn:string;trip:TripRequest;offers:V8StayOffer[];lang?:Lang;missionId?:string|null};
const say=(lang:Lang,el:string,en:string)=>lang==="el"?el:en;
const providerPrice=(offer:V8StayOffer,lang:Lang)=>offer.price!=null&&offer.price>0?`${offer.price.toLocaleString(lang==="el"?"el-GR":"en-GB",{maximumFractionDigits:2})} ${offer.currency||"EUR"}`:say(lang,"Τιμή στον πάροχο","Price at provider");
const safeUrl=(value:unknown)=>typeof value==="string"&&/^https:\/\//i.test(value.trim())?value.trim():null;
function collectUrls(value:unknown,out:Set<string>,depth=0){if(depth>3||out.size>=10||value==null)return;if(typeof value==="string"){const direct=safeUrl(value);if(direct)out.add(direct);else for(const token of value.split(/[|,;\s]+/)){const url=safeUrl(token);if(url)out.add(url)}return}if(Array.isArray(value)){for(const item of value)collectUrls(item,out,depth+1);return}if(typeof value==="object"){for(const[key,item]of Object.entries(value as Record<string,unknown>)){if(/image|photo|picture|gallery|thumb|media/i.test(key))collectUrls(item,out,depth+1)}}}
function stayImages(offer:V8StayOffer|null){if(!offer)return[];const out=new Set<string>();for(const candidate of[offer.imageUrl,offer.thumbUrl]){const url=safeUrl(candidate);if(url)out.add(url)}collectUrls(offer.raw,out);return[...out].slice(0,8)}
function sourceBadge(place:LocalPlaceV38){return place.source==="Google Places"?"GOOGLE":place.source==="Foursquare"?"FOURSQUARE":place.source==="Tripadvisor"?"TRIPADVISOR":"OPEN DATA"}
function aiSignalText(signal:GuestSignalV38|null,lang:Lang){if(!signal||signal.aiScore==null||signal.sampleSize<3)return null;return say(lang,`AI Guest Signal ${signal.aiScore}/100 · ${signal.sampleSize} εμπειρίες`,`AI Guest Signal ${signal.aiScore}/100 · ${signal.sampleSize} experiences`)}
function placeSort(rows:LocalPlaceV38[]){return[...rows].sort((a,b)=>(b.internalSignal?.aiScore??-1)-(a.internalSignal?.aiScore??-1)||(b.rating??-1)-(a.rating??-1)||(b.ratingCount??0)-(a.ratingCount??0)).slice(0,8)}

export function V38EscapeBuilderClient({slug,name,nameEn,trip,offers,lang="el",missionId=null}:Props){
 const destination=lang==="en"?nameEn:name;
 const[selected,setSelected]=useState<V8StayOffer|null>(offers[0]??null),[dossier,setDossier]=useState<Dossier|null>(null),[plan,setPlan]=useState<TripBuilderPlanV25|null>(null),[stage,setStage]=useState<Stage>("cinema"),[tab,setTab]=useState<Tab>("highlights"),[busy,setBusy]=useState(false),[error,setError]=useState<string|null>(null);
 const[media,setMedia]=useState<Media[]>([]),[heroFrame,setHeroFrame]=useState(0),[stayFrame,setStayFrame]=useState(0),[email,setEmail]=useState(""),[mailState,setMailState]=useState<"idle"|"sending"|"sent"|"error">("idle");
 const[feedbackRating,setFeedbackRating]=useState(5),[feedbackRecommend,setFeedbackRecommend]=useState(true),[feedbackComment,setFeedbackComment]=useState(""),[feedbackState,setFeedbackState]=useState<"idle"|"sending"|"sent"|"error">("idle");
 const hero=media[heroFrame]?.imageUrl||selected?.imageUrl||selected?.thumbUrl||null,currentOffer=plan?.stay?.trackingUrl||selected?.trackingUrl||"",guideUrl=plan?.guide.path||"",selectedImages=useMemo(()=>stayImages(selected),[selected]),tripComplete=trip.endDate<=new Date().toISOString().slice(0,10);
 const weatherDays=useMemo(()=>dossier?.weather.days.slice(0,5)??[],[dossier]),local=dossier?.localIntelligence??null;
 const track=(eventName:string,payload:Record<string,unknown>={})=>{if(missionId)void fetch("/api/escape/event",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({missionId,eventName,payload})}).catch(()=>null)};

 useEffect(()=>{let cancelled=false;async function load(){const aerial=await fetch(`/api/escape/media?destination=${encodeURIComponent(nameEn||name)}&mode=aerial`).then(r=>r.ok?r.json():null).catch(()=>null) as {items?:Media[]}|null;let items=aerial?.items??[];if(!items.length){const normal=await fetch(`/api/escape/media?destination=${encodeURIComponent(nameEn||name)}`).then(r=>r.ok?r.json():null).catch(()=>null) as {items?:Media[]}|null;items=normal?.items??[]}if(!cancelled)setMedia(items.slice(0,6))}void load();return()=>{cancelled=true}},[name,nameEn]);
 useEffect(()=>{if(media.length<2)return;const timer=window.setInterval(()=>setHeroFrame(i=>(i+1)%media.length),6800);return()=>window.clearInterval(timer)},[media.length]);
 useEffect(()=>{setStayFrame(0);if(selectedImages.length<2)return;const timer=window.setInterval(()=>setStayFrame(i=>(i+1)%selectedImages.length),5200);return()=>window.clearInterval(timer)},[selected?.sourceProductId,selectedImages.length]);

 async function research(){setBusy(true);setError(null);setStage("research");track("v38_360_research_started",{destinationId:slug});try{if(missionId)await fetch("/api/escape/select",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({missionId,destinationId:slug})}).catch(()=>null);const response=await fetch("/api/escape/research",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({trip,slug})});if(!response.ok)throw new Error(`research_${response.status}`);const data=await response.json() as Dossier;setDossier(data);setStage("explore");track("v38_360_research_completed",{destinationId:slug,providers:data.localIntelligence?.providers??[]})}catch{setError(say(lang,"Ο 360° έλεγχος δεν ολοκληρώθηκε. Η επιλογή σου έχει κρατηθεί — δεν θα γεμίσω τα κενά με εικασίες.","The 360° check did not complete. Your choice is saved — I will not fill gaps with guesses."));setStage("cinema")}finally{setBusy(false)}}
 async function verifyStay(){if(!selected)return;setBusy(true);setError(null);setStage("verify");track("stay_cinema_selected",{destinationId:slug,offerId:selected.sourceProductId});try{const response=await fetch("/api/trip-builder",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({trip,slug,offerId:selected.sourceProductId})});if(!response.ok)throw new Error(`builder_${response.status}`);const built=await response.json() as TripBuilderPlanV25;setPlan(built);setStage("email");if(missionId){const mediaRows=[built.stay?.imageUrl?{kind:"stay",url:built.stay.imageUrl}:null,...(local?.attractions??[]).slice(0,5).map(x=>x.imageUrl?{kind:"place",url:x.imageUrl,name:x.name}:null),...(local?.restaurants??[]).slice(0,5).map(x=>x.imageUrl?{kind:"restaurant",url:x.imageUrl,name:x.name}:null)].filter(Boolean).slice(0,20);void fetch("/api/escape/research/complete",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({missionId,destinationId:slug,weather:built.weather,places:dossier?.research.attractions??[],restaurants:local?.restaurants??[],practicalNotes:dossier?.research.practicalNotes??[],logistics:{availability:built.availability,flexibleWindows:built.flexibleWindows,budgetBeyondHotel:built.budgetBeyondHotel},sources:dossier?.research.sources??[],media:mediaRows,guidePath:built.guide.path,trackingUrl:built.stay?.trackingUrl??selected.trackingUrl})}).catch(()=>null)}}catch{setError(say(lang,"Δεν μπόρεσα να επιβεβαιώσω αυτή τη διαμονή με ασφάλεια. Διάλεξε άλλη βάση — δεν θα εμφανίσω ψεύτικη διαθεσιμότητα.","I could not verify this stay safely. Choose another base — I will not show fake availability."));setStage("stay")}finally{setBusy(false)}}
 async function sendEmail(event:FormEvent){event.preventDefault();if(!selected||!plan||!email)return;setMailState("sending");try{const response=await fetch("/api/guide/email",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({email,slug,start:trip.startDate,end:trip.endDate,offer:selected.sourceProductId,language:lang})});if(!response.ok)throw new Error();if(missionId)await fetch("/api/escape/email-state",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({missionId,email})}).catch(()=>null);setMailState("sent");setStage("unlocked");track("email_gate_completed",{destinationId:slug,offerId:selected.sourceProductId})}catch{setMailState("error")}}
 async function share(){const url=window.location.href,text=say(lang,`Τι λες για ${destination}; Έφτιαξα μια 360° απόδραση για εμάς.`,`What do you think about ${destination}? I built a 360° escape for us.`);if(navigator.share)await navigator.share({title:destination,text,url}).catch(()=>undefined);else await navigator.clipboard.writeText(url).catch(()=>undefined);track("escape_shared",{destinationId:slug})}
 async function sendFeedback(event:FormEvent){event.preventDefault();if(!missionId||!tripComplete)return;setFeedbackState("sending");try{const response=await fetch("/api/escape/feedback",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({missionId,destinationSlug:slug,subjectKind:"destination",subjectKey:`destination:${slug}`,subjectName:destination,went:true,rating:feedbackRating,wouldRecommend:feedbackRecommend,comment:feedbackComment})});if(!response.ok)throw new Error();setFeedbackState("sent")}catch{setFeedbackState("error")}}

 const tabs:Array<{id:Tab;el:string;en:string;count:number}>=[
  {id:"highlights",el:"Μη χάσεις",en:"Don't miss",count:(local?.attractions.length??0)},
  {id:"eat",el:"Φαγητό",en:"Eat",count:(local?.restaurants.length??0)},
