  </section>

  {stage==="research"?<section className={styles.agentStage}><div className={styles.orbit}><i/><i/><i/></div><span>LIVE DESTINATION INTELLIGENCE</span><h2>{say(lang,"Οι agents ξεχωρίζουν το ωραίο από το πραγματικά σωστό.","The agents are separating beautiful from genuinely right.")}</h2><div className={styles.agentRail}><b>{say(lang,"Καιρός","Weather")}</b><b>{say(lang,"Μη χάσεις","Don't miss")}</b><b>{say(lang,"Φαγητό","Food")}</b><b>{say(lang,"Βράδυ","Nightlife")}</b><b>{say(lang,"Πρακτικά","Friction")}</b></div></section>:null}

