   <div className={styles.weatherRail}>{weatherDays.map(day=><article key={day.date}><small>{new Intl.DateTimeFormat(lang==="el"?"el-GR":"en-GB",{weekday:"short",day:"numeric"}).format(new Date(`${day.date}T12:00:00Z`))}</small><strong>{day.temperatureMinC==null?"?":Math.round(day.temperatureMinC)}° <i>→</i> {day.temperatureMaxC==null?"?":Math.round(day.temperatureMaxC)}°</strong><p>{day.summary}</p></article>)}</div>
