   <div className={styles.disclosure}><span>360° DISCLOSURE</span><p>{local?.sourceDisclosure}</p><div>{dossier.research.sources.slice(0,5).map(source=><a href={source.url} target="_blank" rel="noopener nofollow" key={source.url}>{source.domain}</a>)}</div></div>
