const worlds:World[]=[
 {id:"sea",query:"Santorini aerial coast Greece",labelEl:"Θάλασσα & φως",labelEn:"Sea & light",subEl:"Νερό · ήλιος · αργός ρυθμός",subEn:"Water · sun · slow rhythm",semantic:"θέλω θάλασσα, φως, ζεστασιά και αργό ρυθμό",fallbackMood:"warmth"},
 {id:"reset",query:"Madeira aerial green mountains",labelEl:"Reset στη φύση",labelEn:"Nature reset",subEl:"Πράσινο · ανάσα · ησυχία",subEn:"Green · space · quiet",semantic:"θέλω φύση, πράσινο, ησυχία και πραγματικό reset",fallbackMood:"nature"},
 {id:"city",query:"Rome old town aerial evening",labelEl:"Πόλη & βράδυ",labelEn:"City & evenings",subEl:"Βόλτες · φαγητό · ατμόσφαιρα",subEn:"Walking · food · atmosphere",semantic:"θέλω ατμοσφαιρική πόλη, βόλτες, φαγητό και ωραίο βράδυ",fallbackMood:"city"},
 {id:"together",query:"Amalfi coast aerial sunset",labelEl:"Χρόνος για δύο",labelEn:"Time for two",subEl:"Ρομαντικό · όμορφο · χωρίς πίεση",subEn:"Romantic · beautiful · easy",semantic:"θέλω χρόνο για δύο, ρομαντική ατμόσφαιρα και χωρίς πίεση",fallbackMood:"romantic"},
 {id:"adventure",query:"Madeira cliffs aerial ocean",labelEl:"Περιπέτεια",labelEn:"Adventure",subEl:"Τοπίο · κίνηση · κάτι αξέχαστο",subEn:"Landscape · movement · memorable",semantic:"θέλω περιπέτεια, εντυπωσιακή φύση και κάτι που θα θυμάμαι",fallbackMood:"adventure"},
 {id:"surprise",query:"European hidden coastal village aerial",labelEl:"Έκπληξέ με",labelEn:"Surprise me",subEl:"Όχι το προφανές · το σωστό",subEn:"Not obvious · just right",semantic:"βρες κάτι που δεν θα έψαχνα μόνος μου αλλά ταιριάζει πραγματικά",fallbackMood:"relax"}
