const DAY=86_400_000,iso=(d:Date)=>d.toISOString().slice(0,10),add=(d:Date,n:number)=>new Date(d.getTime()+n*DAY);
function nextFriday(){const d=new Date(),u=new Date(Date.UTC(d.getUTCFullYear(),d.getUTCMonth(),d.getUTCDate())),delta=(5-u.getUTCDay()+7)%7||7;return add(u,delta)}
