-columns:1fr 1fr;gap:7px;padding:0 12px 10px}.agentQuick button{border:1px solid rgba(255,255,255,.14);background:rgba(255,255,255,.06);color:#dbeaf2;border-radius:999px;padding:8px;font-size:10px;cursor:pointer}.agentForm{display:flex;gap:6px;padding:10px;border-top:1px solid rgba(255,255,255,.08)}.agentForm input{min-width:0;flex:1;border:1px solid rgba(255,255,255,.14);background:#0d2230;color:#fff;border-radius:12px;padding:10px;outline:none;font-size:10px}.agentForm button{width:36px;border:0;border-radius:50%;background:#e9f6ff;color:#174d73;font-weight:900;cursor:pointer}.content{min-width:0}.breadcrumb{height:34px;display:flex;align-items:center;color:#708295;font-size:10px;padding:0 4px}.hero{display:grid;grid-template-columns:minmax(0,1.35fr) .95fr 290px;gap:8px}.heroMain{height:330px;border-radius:18px;overflow:hidden;position:relative;background:#dbe5ec}.heroMain>img{width:100%;height:100%;object-fit:cover;transition:transform 1s ease}.heroMain:hover>img{transform:scale(1.025)}.heroShade{position:absolute;inset:28% 0 0;background:linear-gradient(transparent,rgba(5,22,36,.78))}.heroCopy{position:absolute;left:20px;right:18px;bottom:17px;color:white;z-index:2}.urgent{display:inline-block;background:#ffefc7;color:#8b5200;border-radius:999px;padding:6px 9px;font-size:9px;font-weight:900;margin-bottom:9px}.heroCopy h1{font-family:Georgia,serif;font-size:32px;margin:0 0 3px;font-weight:500}.stars{color:#ffb228;letter-spacing:.08em}.heroCopy p{margin:5px 0 0;font-size:10px;color:#d7e2e8}.gallery{height:330px;display:grid;grid-template-columns:1fr 1fr;grid-template-rows:1fr 1fr;gap:7px}.gallery>img,.drone{width:100%;height:100%;object-fit:cover;border-radius:14px;overflow:hidden;position:relative;background:#d9e2e8}.drone img{width:100%;height:100%;object-fit:cover}.drone:after{content:"";position:absolute;inset:50% 0 0;background:linear-gradient(transparent,rgba(7,24,35,.75))}.drone span{position:absolute;left:10px;bottom:9px;z-index:2;color:white;font-size:9px