    <div className={styles.topMeta}><span>{mapMeta.count?mapMeta.count.toLocaleString("el-GR"):"…"} stays</span><span>{mapMeta.locationCount?mapMeta.locationCount.toLocaleString("el-GR"):"…"} areas</span></div>
  </header>

