async function wikiSource(host:string,query:string,maxChars:number):Promise<{title:string;text:string;url:string}|null>{try{const search=new URL(`https://${host}/w/api.php`);search.search=new URLSearchParams({action:"query",list:"search",srsearch:query,srlimit:"1",format:"json",formatversion:"2",origin:"*"}).toString();const s=await fetch(search,{next:{revalidate:86400},signal:AbortSignal.timeout(3500)});if(!s.ok)return null;const sj=await s.json() as WikiSearch,title=sj.query?.search?.[0]?.title;if(!title)return null;const extract=new URL(`https://${host}/w/api.php`);extract.search=new URLSearchParams({action:"query",prop:"extracts",explaintext:"1",redirects:"1",titles:title,format:"json",formatversion:"2",origin:"*"}).toString();const e=await fetch(extract,{next:{revalidate:86400},signal:AbortSignal.timeout(4000)});if(!e.ok)return null;const ej=await e.json() as WikiExtract,row=ej.query?.pages?.[0],text=clean(row?.extract,maxChars);if(!text)return null;return{title:row?.title??title,text,url:`https://${host}/wiki/${encodeURIComponent(slug(row?.title??title))}`}}catch{return null}}
function parseJson(raw:string):ResearchJson{const cleaned=raw.replace(/^```(?:json)?\s*/i,"").replace(/\s*```$/i,"").trim(),a=cleaned.indexOf("{"),b=cleaned.lastIndexOf("}");if(a<0||b<=a)throw new Error("Invalid research JSON");return JSON.parse(cleaned.slice(a,b+1)) as ResearchJson}
function place(item:NonNullable<ResearchJson["things_to_do"]>[number],i:number,category:"ATTRACTION"|"RESTAURANT"|"OTHER"):DestinationResearchPlace|null{const name=clean(item.name,140),summary=clean(item.summary,280);if(!name||!summary)return null;return{id:`research-${i}-${name.toLowerCase().replace(/[^a-z0-9α-ωάέήίόύώϊϋ]+/gi,"-").slice(0,36)}`,name,category,summary,whyItFits:clean(item.why_it_fits,180)||null,evidenceStrength:item.evidence_strength??"MEDIUM",rating:null,reviewCount:null,imageUrl:null,address:null,distanceKm:null,attribution:"Wikivoyage/Wikipedia synthesis"}}
function pulse(item:NonNullable<ResearchJson["review_pulse"]>[number],i:number):DestinationResearchReview|null{const t=clean(item.summary,320);if(!t)return null;return{id:`pulse-${i}`,title:clean(item.title,100)||"Travel guide pulse",text:t,rating:null,publishedDate:null,author:"Travel Guru research",evidenceStrength:item.evidence_strength??"MEDIUM"}}

